const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { ExecutiveCompensationDb } = require('../models/executive');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/hr.key'),
  cert: fs.readFileSync('/etc/ssl/hr.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://executive.hr.internal');

  if (url.pathname === '/hr/executive-portal') {
    const departmentId = url.searchParams.get('departmentId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Unauthorized');
    }

    let caller;
    try {
      caller = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    // Verify caller possesses Compensation Committee executive authorization
    if (!caller.roles || !caller.roles.includes('COMP_COMMITTEE_DIRECTOR')) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: Compensation Committee role required');
    }

    if (departmentId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/payroll/executive/${departmentId}/salaries.json` }, async (err, pushStream) => {
        if (err) return;
        const compensation = await ExecutiveCompensationDb.findByDepartment(departmentId);
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify(compensation));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Executive Compensation Board</body></html>');
  }
});

server.listen(8450);
